import { Form } from "@lifesg/react-design-system/form";
import { Toggle } from "@lifesg/react-design-system/toggle";
import clsx from "clsx";
import { useEffect, useState } from "react";
import sanitize from "sanitize-html";
import * as Yup from "yup";
import { IGenericFieldProps } from "..";
import { TestHelper, filterSchemaProps } from "../../../utils";
import { useValidationConfig } from "../../../utils/hooks";
import { Warning } from "../../shared";
import * as styles from "./switch.styles";
import { ISwitchSchema } from "./types";

export const Switch = (props: IGenericFieldProps<ISwitchSchema>) => {
	// =============================================================================
	// CONST, STATE, REFS
	// =============================================================================
	const { error, formattedLabel, id, onChange, schema, value, warning } = props;
	const {
		commonSchema: { customOptions, label, validation },
		customSchema: { className, disabled, ...toggleProps },
	} = filterSchemaProps(schema);

	const [stateValue, setStateValue] = useState<boolean>(value || undefined);
	const { setFieldValidationConfig } = useValidationConfig();

	// =============================================================================
	// EFFECTS
	// =============================================================================
	useEffect(() => {
		setFieldValidationConfig(id, Yup.boolean().strict(), validation);
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [validation]);

	useEffect(() => {
		setStateValue(value);
	}, [value]);

	// =============================================================================
	// EVENT HANDLERS
	// =============================================================================
	const handleClick = (value: boolean) => {
		onChange({ target: { value } });
	};

	// =============================================================================
	// HELPER FUNCTIONS
	// =============================================================================
	const isSwitchChecked = (value: boolean) => {
		return stateValue === value;
	};

	const formatId = (type: string) => {
		return `${id}-${type}`;
	};

	// =========================================================================
	// RENDER FUNCTIONS
	// =========================================================================
	return (
		<>
			<Form.CustomField id={id} label={formattedLabel} errorMessage={error?.message}>
				<div
					className={clsx(styles.flexWrapper, className)}
					role="radiogroup"
					aria-label={typeof label === "string" ? label : sanitize(label.mainLabel, { allowedTags: [] })}
				>
					<Toggle
						{...toggleProps}
						type="yes"
						id={formatId("yes")}
						data-testid={TestHelper.generateId(id, "switch-yes")}
						disabled={disabled}
						styleType={customOptions?.border === false ? "no-border" : "default"}
						checked={isSwitchChecked(true)}
						onChange={() => handleClick(true)}
						indicator={true}
						name={id}
						error={!!error?.message}
					>
						Yes
					</Toggle>
					<Toggle
						{...toggleProps}
						type="no"
						id={formatId("no")}
						data-testid={TestHelper.generateId(id, "switch-no")}
						disabled={disabled}
						styleType={customOptions?.border === false ? "no-border" : "default"}
						checked={isSwitchChecked(false)}
						onChange={() => handleClick(false)}
						indicator={true}
						name={id}
						error={!!error?.message}
					>
						No
					</Toggle>
				</div>
			</Form.CustomField>
			<Warning id={id} message={warning} />
		</>
	);
};
